'use strict';
const $=id=>document.getElementById(id),C=HOHCards;

let enteredGame=false;
let openingDealCounts=null,drawingDeckBack=null;
let leavingMenu=false;
let game,paused=false,pumping=false,pendingReaction=null,choiceResolve=null,generation=0;
const wait=ms=>new Promise(r=>setTimeout(r,ms));
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function renderBacks(){
 const deck=document.querySelector('.deck'),back=drawingDeckBack||(game.deck.length?C.byId[game.deck[0]].back:null);
 deck.classList.toggle('sun-located',game.sunLocation?.zone==='deck');deck.classList.toggle('standard',back==='standard');deck.classList.toggle('purple',back==='purple');deck.classList.toggle('empty',!back);
 deck.disabled=!back||game.ended||game.busy||paused||game.phase!=='turn'||Boolean(pendingReaction)||game.control(game.players[game.turn])!==0||!game.players[game.turn].alive;
 deck.onclick=()=>{if(!deck.disabled)act(()=>game.endTurn());};
 deck.setAttribute('aria-label',back?'Draw a card and end your turn · '+(back==='standard'?'crimson basic back':'purple special back'):'Draw pile empty');
 deck.title=back==='standard'?'Crimson: Utility or Heart card':back==='purple'?'Purple: Legendary, Relic, Joker or Instant':'No cards remaining';
 if(!document.getElementById('back-key')){const key=el('div','back-key');key.id='back-key';key.append(el('span','basic-key','Crimson · Basic / Heart'),el('span','special-key','Purple · Special'));key.title='Purple backs include Legendaries, Relics, Jokers, Dud and Instants.';document.querySelector('.hand-heading').before(key);}
}
function cardNode(id,small=false){const ward=game?.players.find(p=>p.ward?.angel===id&&p.ward.copiedSource)?.ward;if(ward)return copiedCardNode(id,ward.copiedSource,small);const c=C.byId[id],node=el('div','card '+c.type+(small?' small':''));node.dataset.card=id;if(id==='Sun'&&game?.sunLocation)node.classList.add('sun-located');const top=el('div','card-top');top.append(el('span','',c.rank+c.suit),el('span','card-type',c.classification==='relic'?'Relic':c.type==='joker'?'Legendary':c.type==='bad'?'End game':c.type==='dud'?'':c.type==='instant'?'⚡ Instant':c.type));const art=el('div','card-art');art.innerHTML=HOHArt.markup(c.art||c.effect);node.append(top,art,el('div','card-name',c.name),el('div','card-text',c.effect==='reaper'?'Lose 1 Heart.':c.text));if(c.type==='joker'){const badge=el('span','joker-badge');badge.innerHTML=HOHArt.markup('joker2');badge.setAttribute('aria-hidden','true');node.append(badge);const mirrored=badge.cloneNode(true);mirrored.classList.add('joker-badge-opposite');node.append(mirrored);for(const side of ['left','right']){const label=el('span','joker-index '+side,'JOKER');label.setAttribute('aria-hidden','true');node.append(label);}}if(c.effect==='reaper'){const count=game?.reaperHearts?.[id]||0,slots=el('div','reaper-slots');slots.setAttribute('aria-label',count+' of 5 Hearts taken');for(let i=0;i<5;i++)slots.append(el('span',i<count?'filled':'empty',i<count?'♥':'♡'));node.append(slots);}node.title=c.rulesText||c.text;return node;}
function button(text,fn,cls=''){const b=el('button',cls,text);b.type='button';b.onclick=fn;return b}
function seat(p){
 if(openingDealCounts)p={...p,hand:p.hand.slice(0,openingDealCounts[p.id])};
 const n=el('div',`seat seat-${p.id}${game.turn===p.id&&!game.ended?' active':''}${!p.alive?' dead':''}`);n.id='seat-'+p.id;
 const info=el('div','seat-info'),name=el('div','seat-name');name.append(el('span','avatar',['I','II','III','IV'][p.id]),document.createTextNode(p.name));
 const hearts=el('div','hearts');hearts.setAttribute('aria-label',`${p.hearts} of ${p.max} Hearts`);hearts.append(el('span','','♥'.repeat(p.hearts)),el('span','empty-heart','♡'.repeat(p.max-p.hearts)));
 info.append(name,hearts,el('div','seat-caption',p.alive?`${p.hand.length} cards · ${p.hearts}/${p.max} Hearts${p.skip?' · skip pending':''}${p.nextController!==undefined&&p.nextController!==null?' · controlled next':''}`:'ELIMINATED'));if(p.legendaryCursed)info.append(el('div','seat-caption','Crocodile curse · no Legendary plays'));if(p.blessed)info.append(el('div','seat-caption','✧ Final Blessing · ending Heart loss prevented'));if(p.encoreActive)info.append(el('div','seat-caption','Encore · '+(2-game.legendaryUsed)+' Legendary plays left'));n.append(info,HOHCharacters.node(p));
 if(p.id!==0){const backs=el('div','mini-hand');backs.setAttribute('aria-label',p.name+' hidden hand');for(const id of p.hand){if(p.revealed?.includes(id)){const shown=cardNode(id,true);shown.classList.add('revealed-hand-card');backs.append(shown);continue;}const back=C.byId[id].back;const b=el('span','mini-back '+back,'✧');b.setAttribute('aria-label',back==='standard'?'Crimson basic card back':'Purple special card back');backs.append(b)}n.append(backs)}
 const pendingInstants=[]; if(p.effects.length||p.ward||pendingInstants.length){
 const area=el('div','face-up-area');area.append(el('div','face-up-heading','IN FRONT OF '+(p.id===0?'YOU':p.name.toUpperCase())));
 const effects=el('div','effects');for(const item of pendingInstants){const face=cardNode(item.card);face.append(el('div','effect-placement','RESOLVING'));effects.append(face);}for(const [i,e]of p.effects.entries()){
 const face=e.copiedSource?copiedCardNode(e.card,e.copiedSource):cardNode(e.card);face.classList.add('persistent-card');face.dataset.effectCard=e.card;face.querySelector('.card-type').textContent='Face-up';const ongoing={bloodpact:'Linked holders lose Hearts together. If one dies, both die.',torment:'Start of your turn: spin the wheel. Broken Heart: lose 1 Heart. Heart: restore 1 Heart.',parasite:'You die at game end.',heartbreak:'You lose 1 Heart at game end.',cursed:'You cannot play Heart cards, including Legendaries.',sacrifice:'Cannot play Legendaries. Remove by returning 1 hand Legendary, using 1 action.'};if(ongoing[game.effectType(e)])face.querySelector('.card-text').textContent=ongoing[game.effectType(e)];
 if(e.copiedEffect&&!e.copiedSource){const copied=C.cards.find(c=>c.effect===e.copiedEffect);face.querySelector('.card-name').textContent=C.byId[e.card].name+' · '+e.copiedName;face.querySelector('.card-art').innerHTML=HOHArt.markup(e.copiedEffect);if(copied)face.querySelector('.card-text').textContent=copied.text;}
 if(game.effectType(e)==='puppet'){const owner=game.players[e.owner];face.querySelector('.card-text').textContent=`If ${p.name} achieves either of the first two Win Conditions, ${owner?.name||'the Puppet Master owner'} wins instead. `;face.append(el('div','effect-placement','FACE-UP · WIN REDIRECT'));}else face.append(el('div','effect-placement','FACE-UP · ACTIVE'));
 const cost=game.effectType(e)==='sacrifice'?1:2;if(game.effectType(e)!=='bloodpact'&&game.turn===p.id&&game.control(p)===0&&game.legendaries(p).length>=cost&&game.used<game.cfg.basicLimit&&!game.busy&&!game.ended)face.append(button('Remove effect',()=>act(()=>game.removeEffect(i))));
 effects.append(face);
 }
 if(p.ward){const ward=el('div','protected-card back purple');ward.append(el('span','','✦'),el('b','','H♥H'),el('span','ward-label','FACE-DOWN'),el('span','ward-label','Protected Legendary'));if(game.sunLocation?.zone==='ward'&&game.sunLocation.player===p.id)ward.classList.add('sun-located');ward.title=p.id===0?C.byId[p.ward.card].name:'A protected Legendary; identity hidden';effects.append(ward);}
 area.append(effects);n.append(area);
 }
 return n;
}
function render(){if(!game)return;updatePrivateLegendaryCount();renderBacks();$('opponents').replaceChildren(...game.players.slice(1).map(seat));$('human-seat').replaceChildren(seat(game.players[0]));$('deck-count').textContent=game.deck.length;$('discard-count').textContent=game.discard.length+game.table.length;const played=game.table.filter(t=>C.byId[t.card]?.type!=='instant').at(-1);const pendingInstant=game.table.find(t=>C.byId[t.card]?.type==='instant');renderInstantStage(pendingInstant);const topCard=played?.card||game.discard.at(-1);$('played').replaceChildren(topCard?(played?.displayCard?copiedCardNode(topCard,played.displayCard,true):cardNode(topCard,true)):el('span','','♥'));$('play-label').textContent=played?`${game.players[played.actor].name.toUpperCase()} · ${played.label.toUpperCase()}`:'PLAY CARDS HERE';const p=game.players[game.turn],humanControl=game.control(p)===0&&p.alive;const visible=pendingReaction?game.players[pendingReaction.subject]:humanControl?p:game.players[0];$('hand-kicker').textContent=visible.id===0?'YOUR PRIVATE HAND':`CONTROLLING ${visible.name.toUpperCase()} · PRIVATE HAND`;$('turn-title').textContent=game.ended?'The table has spoken.':humanControl?'Make your move.':`${p.name}’s turn`;$('allowance').textContent=`${game.used} / ${game.cfg.basicLimit} basic cards played${game.lockdownTurns?' · Lockdown active':''}`;$('draw-button').disabled=!humanControl||game.busy||paused||game.ended||Boolean(pendingReaction);$('hand').replaceChildren();const orderedHand=[...(openingDealCounts?visible.hand.slice(0,openingDealCounts[visible.id]):visible.hand)];sortCards(orderedHand);for(const id of orderedHand){const n=cardNode(id);const c=C.byId[id];if(pendingReaction&&pendingReaction.subject===visible.id&&pendingReaction.options.includes(id)){n.append(button(['rankcopy','exactcopy'].includes(c.effect)?'Use '+c.name:c.effect==='crocodile'?'Crocodile Tears':c.effect==='wildcard'?'Use Wildcard':c.effect==='hijack'?'Hijack':c.effect==='silence'?'Silence':c.effect==='alter'?'Return Instant':c.effect==='inherit'?'Inherit':c.effect==='block'?'Block':'Destroy Instant',()=>pendingReaction?.resolve(id),'reaction-button'));}else if(!['win','bad','dud'].includes(c.type)&&!['revive','silence','hijack','inherit','alter','block','nullifier','crocodile'].includes(c.effect)){const enabled=humanControl&&!paused&&!game.busy&&!game.ended&&game.legal(p,id);if(enabled){n.classList.add('click-to-play');n.tabIndex=0;n.setAttribute('role','button');n.setAttribute('aria-label','Play '+c.name);n.onclick=()=>act(()=>game.play(id));n.onkeydown=e=>{if(e.target!==n)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();n.click();}}}}else if(!['win','bad','dud'].includes(c.type))n.append(el('div','card-type',c.effect==='revive'?'AUTOMATIC AT DEATH':c.effect==='crocodile'?'AUTOMATIC AT 1 HEART':'REACTION ONLY'));$('hand').append(n)}if(!visible.hand.length)$('hand').append(el('div','empty-hand',visible.alive?'Your hand is empty. Draw to end your turn.':'You have been eliminated. Watch the table play out.'));$('hint').textContent=humanControl?('Play up to 3 Utility / Heart cards, then a Legendary or draw.'):'Your hand stays private. You can still react to eligible cards.';$('last-log').textContent=game.log.at(-1)||'';$('log').replaceChildren(...game.log.slice().reverse().map(t=>el('li','',t)));if(!pendingReaction)$('status').textContent=game.ended?game.result?.reason:paused?'Game paused':game.busy?(game.log.at(-1)||'Resolving…'):humanControl?'Your turn · choose a card or draw':`${p.name} is considering the table…`;if(!enteredGame){$('status').textContent='';$('turn-title').textContent='';$('hint').textContent='';$('allowance').textContent='';}paintBoardSelection();window.HOHGameUX?.render(game,enteredGame,paused);}
async function fly(event){render();const id=event.card;if(!id)return;if(C.byId[id].type==='joker')$('played').querySelector('.card')?.classList.add('joker-play-laugh');if(C.byId[id].type==='instant'&&lastInstantSound===id)lastInstantSound=null;else playCardSfx(id);const instant=C.byId[id].type==='instant',landed=(instant?$('instant-stage'):$('played')).querySelector('.card');if(!landed)return;if(instant){const stage=$('instant-stage');stage.classList.remove('instant-flash');void stage.offsetWidth;stage.classList.add('instant-flash');}const reduce=HOHSettings.low()||matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduce){const n=landed.cloneNode(true),to=landed.getBoundingClientRect(),from=(instant?$('draw-pile'):$('seat-'+event.actor))?.getBoundingClientRect()||to;const dx=Math.max(-innerWidth*.65,Math.min(innerWidth*.65,from.left+from.width/2-to.left-to.width/2)),dy=Math.max(-innerHeight*.65,Math.min(innerHeight*.65,from.top+from.height/2-to.top-to.height/2));freezeFlightAppearance(landed,n);n.classList.add('flying','depth-flight');Object.assign(n.style,{position:'fixed',zIndex:'100',margin:'0',right:'auto',bottom:'auto',maxWidth:to.width+'px',left:to.left+'px',top:to.top+'px',width:to.width+'px',minWidth:to.width+'px',height:to.height+'px',minHeight:to.height+'px',maxHeight:to.height+'px',padding:getComputedStyle(landed).padding,transition:'none'});document.body.append(n);landed.style.visibility='hidden';try{const animation=n.animate([{transform:`perspective(900px) translate(${dx}px,${dy}px) rotateX(12deg) rotateY(-9deg) rotateZ(-5deg) scale(.86)`,boxShadow:'0 8px 16px #0005'},{offset:.62,transform:`perspective(900px) translate(${dx*.15}px,${dy*.15-18}px) rotateX(5deg) rotateY(5deg) rotateZ(2deg) scale(1.035)`,boxShadow:'0 28px 34px #0007'},{transform:'perspective(900px) translate(0,0) rotateX(0) rotateY(0) rotateZ(0) scale(1)',boxShadow:'0 5px 12px #0005'}],{duration:850,easing:'cubic-bezier(.22,.68,.25,1)',fill:'forwards'});await animation.finished;}catch{}finally{landed.style.removeProperty('visibility');n.remove();}}await wait(instant?Math.max(1500,game.cfg.paceMs*.6):220);}

async function showExposedHeart(e){
 const scene=el('section','exposed-heart-scene');scene.setAttribute('role','status');
 scene.append(el('small','',game.players[e.player].name+' · EXPOSED HEART'));
 const row=el('div','exposed-heart-cards');for(const id of e.cards)row.append(cardNode(id));
 scene.append(row,el('p','',e.cards.length?'Returning to their hand…':'No hand Legendaries to reveal.'));
 document.body.append(scene);try{await wait(e.cards.length?3000:1200);}finally{scene.remove();}
}
async function event(e){if(e.type==='exposed-heart-reveal'){await showExposedHeart(e);return;}if(e.type==='damage')HOHCharacters.trigger(e.player,'hurt');if(e.type==='play'||e.type==='copy')HOHCharacters.trigger(e.actor,['legendary','joker'].includes(C.byId[e.card]?.type)?'legendary':'play');if(e.type==='pass-move'){await animatePass(e);}else if(e.type==='copy-transform'){await animateCopyTransform(e);}else if(e.type==='rewind-start'){await animateRewind(e.moves);}else if(e.type==='damage'){window.HOHGameUX?.damage(e.player);playDamageSfx(e.amount);render();}else if(e.type==='heal'){playHealSfx(e.amount>1||game.table.some(t=>C.byId[t.displayCard||t.card]?.effect==='wave')?2:1);render();}else if(e.type==='seeker'){render();await wait(2500);}else if(e.type==='announcement'){render();await wait(game.cfg.paceMs);}else if(e.type==='play'||e.type==='copy'){if(/reviv|Second Chance/.test(game.table.find(t=>t.serial===e.serial)?.label||''))HOHSounds.revive();await fly(e);}else if(e.type==='move'){HOHSounds.finishInstant(e.card);render();await wait(game.cfg.paceMs*.3);}else if(e.type==='turn'){render();await wait(game.cfg.paceMs);}else if(e.type==='torment-roll'){const wheel=el('div','torment-wheel-scene');wheel.setAttribute('role','status');const title=el('small','',game.players[e.player].name+' · TORMENT'),spinner=el('div','fortune-wheel');for(const [symbol,angle] of [['💔',90],['♥',270]]){const label=el('span','wheel-symbol',symbol);label.style.setProperty('--angle',angle+'deg');spinner.append(label);}const pointer=el('div','wheel-pointer','▼'),result=el('p','wheel-result');wheel.append(title,pointer,spinner,result);document.body.append(wheel);const rotation=1800-(e.value===5?90:270);if(!HOHSettings.low()&&!matchMedia('(prefers-reduced-motion: reduce)').matches){try{await spinner.animate([{transform:'rotate(0deg)'},{transform:'rotate('+rotation+'deg)'}],{duration:1300,easing:'cubic-bezier(.15,.7,.2,1)',fill:'forwards'}).finished;}catch{}}else spinner.style.transform='rotate('+rotation+'deg)';result.textContent=e.value===5?'💔 Lose 1 Heart':'♥ Restore 1 Heart';await wait(HOHSettings.low()?250:600);wheel.remove();}else if(e.type==='draw-lift'){drawingDeckBack=e.back;renderBacks();}else if(e.type==='draw'){playDrawSfx(e.back,e.instant,e.instantCard);if(e.instant){drawingDeckBack=null;render();await wait(250);}else await drawFlight(e);}else if(e.type==='draw-arrived'){render();}else if(e.type==='end'){HOHSounds.stopAll();render();showEnding();}else render();}
function botChoice(pid,title,opts,meta){const p=game.players[meta.subject??pid],value=id=>game.botValue(p,id);if(meta.kind==='steal-back'){const preferred=p.hearts<=1&&game.rng()<.65?'standard':'purple';const pool=opts.filter(o=>o.back===preferred);const available=pool.length?pool:opts;return available[Math.floor(game.rng()*available.length)].value;}if(meta.kind==='player')return game.botTarget(p,title,opts);if(meta.kind==='effect'){const own=opts.filter(o=>String(o.value).startsWith(p.id+':'));return (own.length?own:opts)[0].value;}if(meta.kind==='search'){const c=C.byId[opts[0].card];return c.type==='instant'?'skip':value(c.id)>=60?'take':'skip';}if(meta.kind==='pandora')return [...opts].sort((a,b)=>value(b.card)-value(a.card))[0].value;if(meta.kind==='card')return [...opts].sort((a,b)=>/give|return/i.test(title)?value(a.card)-value(b.card):value(b.card)-value(a.card))[0].value;return opts[0].value;}
function decisionContext(title,meta){
 const source=game.table.at(-1),subject=game.players[meta.subject];
 const controlled=subject&&subject.id!==0?` You are making this choice for ${subject.name}.`:'';
 if(!source)return 'You chose to remove a face-up effect. Return two Legendaries from your hand to pay its cost.'+controlled;
 const card=C.byId[source.card],actor=game.players[source.actor];
 const action=source.actor===0?`You played ${card.name}.`:`${actor.name} played ${card.name}.`;
 let reason=card.text;
 if(card.effect==='shuffle'&&meta.kind==='card')reason=source.actor===meta.subject?'Choose one of your Legendaries to shuffle back into the draw pile.':`${subject?.id===0?'You were':subject.name+' was'} targeted. Choose one Legendary to shuffle back into the draw pile.`;
 if(card.effect==='swap'&&meta.kind==='card')reason='Each player chooses which Legendary from their own hand to exchange.';
 if(card.effect==='upper'&&meta.kind==='card')reason='Upper Hand requires the targeted player to give a Full Moon of their choice. Heart of the Sun cannot be taken.';
 if(card.effect==='inherit')reason='Inheritance lets you privately inspect these returning cards and take one.';
 return action+' '+reason+controlled+' The game waits for your choice.';
}
async function choose(pid,title,opts,meta){if(pid!==0){await wait(game.cfg.paceMs*.5);return botChoice(pid,title,opts,meta);}if(meta?.kind==='player'||title==='Choose the effect to pass')return chooseOnBoard(title,opts,meta?.kind==='player'?'player':'effect',meta.subject);render();$('choice').classList.toggle('pandora-choice',meta?.kind==='pandora');$('choice-title').textContent=title;$('choice-context').textContent=decisionContext(title,meta);$('choice-options').replaceChildren();return new Promise(resolve=>{let done=false;const countdown=el('p','decision-countdown'),deadline=Date.now()+30000;const finish=value=>{if(done)return;done=true;clearInterval(timer);$('choice').close();choiceResolve=null;resolve(value);};choiceResolve=finish;const tick=()=>{const left=Math.max(0,Math.ceil((deadline-Date.now())/1000));countdown.textContent=left+'s to decide';if(left===0)finish(opts[0]?.value);};const timer=setInterval(tick,200);for(const opt of opts){if(opt.back){const back=button('♥',()=>finish(opt.value),'steal-choice-back '+opt.back);back.setAttribute('aria-label',opt.label);$('choice-options').append(back);}else if(opt.card){const wrap=el('div','choice-option');if(meta?.kind==='pandora'){const card=cardNode(opt.card);card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label','Choose '+opt.label);card.onclick=()=>finish(opt.value);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();finish(opt.value);}};wrap.append(card);}else wrap.append(cardNode(opt.card),button(opt.label,()=>finish(opt.value),'primary'));$('choice-options').append(wrap);}else $('choice-options').append(button(opt.label,()=>finish(opt.value),'plain-choice'));}$('choice-options').append(countdown);tick();$('choice').showModal();});}

async function react(pid,ctx){if(pid!==0){await wait(game.cfg.paceMs*(.7+game.rng()*.6));const p=game.players[ctx.subject];if(ctx.kind==='instant'){if(ctx.actor!==p.id)return null;return ctx.options[0];}if(ctx.kind==='crocodile'||ctx.kind==='inherit'||ctx.kind==='utility'||ctx.kind==='revive')return ctx.options[0];const hijack=ctx.options.find(id=>C.byId[id].effect==='hijack');if(hijack&&p.hearts>1&&game.rng()<.7)return hijack;return game.rng()<.55?ctx.options.find(id=>C.byId[id].effect==='silence')||null:null;}return new Promise(resolve=>{let settled=false;const end=val=>{if(settled)return;settled=true;clearInterval(timer);pendingReaction=null;$('reaction-status').replaceChildren();resolve(val);render();};pendingReaction={...ctx,resolve:end};const deadline=Date.now()+ctx.ms;const tick=()=>{const left=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('reaction-status').replaceChildren(el('span','',`${ctx.kind==='legendary'?'Legendary reaction':ctx.kind==='instant'?'Instant response':ctx.kind==='utility'?'Block opportunity':ctx.kind==='crocodile'?'Crocodile Tears':'Inheritance opportunity'} · ${left}s `),button('Pass',()=>end(null)));if(left===0)end(null);};const timer=setInterval(tick,200);render();tick();});}
async function act(fn){await fn();sortCards(game.players[0].hand);render();pump();}
async function pump(){if(!enteredGame||pumping)return;pumping=true;const gen=generation;try{while(gen===generation&&!game.ended){if(paused){await wait(200);continue;}const p=game.players[game.turn];if(game.control(p)===0)break;await wait(game.cfg.paceMs);if(paused||gen!==generation||game.busy||game.players[game.turn]!==p)continue;const removable=p.effects.findIndex(e=>['torment','parasite','heartbreak','cursed','puppet','sacrifice'].includes(game.effectType(e)));if(removable>=0&&game.used<game.cfg.basicLimit&&game.legendaries(p).length>=3&&(game.deck.length<12||p.hearts<2)){await game.removeEffect(removable);continue;}const move=game.botAction(p);if(move)await game.play(move);else await game.endTurn();}}catch(err){console.error(err);$('status').textContent='A game error occurred: '+err.message;}finally{pumping=false;render();}}
function showEnding(){$('winner').textContent=game.result.winners.length?game.result.winners.map(i=>i===0?'You':game.players[i].name).join(' & ')+(game.result.winners.length===1?(game.result.winners[0]===0?' win.':' wins.'):' share the win.'):'No survivors.';$('win-reason').textContent=game.result.reason;$('scores').replaceChildren(...game.players.map(p=>{const row=el('div','result-row');row.append(el('b','',p.name),el('span','',p.alive?`${p.hearts} Hearts · ${game.owned(p).filter(id=>game.isLegend(id)).length} Legendaries`:'Eliminated'));const cards=el('div','final-cards');for(const id of p.hand)cards.append(cardNode(id));if(p.ward){const protectedCard=el('div','final-protected');protectedCard.append(el('div','','Protected card'),cardNode(p.ward.card));cards.append(protectedCard);}if(!cards.children.length)cards.append(el('span','','No cards remaining.'));row.append(cards);return row;}));$('ending').showModal();}
