function soundBus(ctx){if(ctx.hohBus)return ctx.hohBus;const input=ctx.createGain(),compress=ctx.createDynamicsCompressor(),filter=ctx.createBiquadFilter(),room=ctx.createConvolver(),wet=ctx.createGain();filter.type='lowpass';filter.frequency.value=6500;compress.threshold.value=-20;compress.ratio.value=3;input.gain.value=1.3;input.connect(filter);filter.connect(compress);compress.connect(HOHSettings.effectBus(ctx));const buffer=ctx.createBuffer(2,Math.floor(ctx.sampleRate*.65),ctx.sampleRate);for(let ch=0;ch<2;ch++){const d=buffer.getChannelData(ch);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,3);}room.buffer=buffer;wet.gain.value=.18;filter.connect(room);room.connect(wet).connect(compress);ctx.hohBus=input;return input;}
function playShuffleSfx(){if(!enteredGame&& !leavingMenu)return;try{const ctx=soundContext();for(let i=0;i<13;i++)instantNoise(ctx,i*.065,.13,.08+(i%3)*.015,1600+(i%4)*350,500);soundTone(ctx,100,.88,.18,.08,'sine',60);instantNoise(ctx,.87,.2,.1,900,300);}catch{}}
async function dealOpeningHands(){openingDealCounts=[0,0,0,0];render();$('status').textContent='';playShuffleSfx();await wait(1100);for(let i=0;i<5;i++)for(const p of game.players){const id=p.hand[i];playDealSlide();await drawFlight({player:p.id,back:C.byId[id].back});openingDealCounts[p.id]++;render();$('status').textContent='';}openingDealCounts=null;render();await showInstantSetup();}

const historyButton=button('History',()=>{$('history-log').replaceChildren(...game.log.slice().reverse().map(t=>el('li','',t)));$('history-dialog').showModal();});historyButton.id='history-button';$('rules-button').after(historyButton);$('status').setAttribute('aria-live','polite');

function renderInstantStage(item){let stage=$('instant-stage');if(!stage){stage=el('section','instant-reveal');stage.id='instant-stage';stage.setAttribute('aria-live','polite');document.querySelector('.table').append(stage);}stage.hidden=!item;if(!item){stage.replaceChildren();delete stage.dataset.card;return;}if(stage.dataset.card!==item.card){stage.dataset.card=item.card;stage.replaceChildren(el('div','instant-stage-label',game.players[item.actor].name+' drew an Instant'),cardNode(item.card),el('div','instant-stage-note','Resolving…'));}}

function playDealSlide(){try{const ctx=soundContext();instantNoise(ctx,0,.14,.045,1300,550);}catch{}}
async function showInstantSetup(){const tray=el('section','instant-setup-tray'),label=el('h2','',''),row=el('div','instant-setup-backs');tray.append(label,row);for(let i=0;i<C.cards.filter(c=>c.type==='instant').length;i++){const back=el('div','setup-instant-back','♥');back.setAttribute('aria-label','Face-down Instant');row.append(back);}document.querySelector('.table').append(tray);$('status').textContent='';await wait(1200);const pile=$('draw-pile').getBoundingClientRect();for(const back of [...row.children]){const rect=back.getBoundingClientRect();playDealSlide();if(!(HOHSettings.low()||matchMedia('(prefers-reduced-motion: reduce)').matches)){try{await back.animate([{transform:'none',opacity:1},{transform:'translate('+(pile.left+pile.width/2-rect.left-rect.width/2)+'px,'+(pile.top+pile.height/2-rect.top-rect.height/2)+'px) scale(.75)',opacity:0}],{duration:220,easing:'ease-in',fill:'forwards'}).finished;}catch{}}back.style.visibility='hidden';}playShuffleSfx();label.textContent='';const motion=matchMedia('(prefers-reduced-motion: reduce)').matches?null:$('draw-pile').animate([{transform:'rotate(0)'},{transform:'translateX(-6px) rotate(-4deg)'},{transform:'translateX(6px) rotate(4deg)'},{transform:'rotate(0)'}],{duration:380,iterations:3});await wait(1200);motion?.cancel();tray.remove();render();}

const lobbyRules=button('Read rules',()=>{$('rules').inert=false;$('rules').showModal();},'lobby-rules');$('enter-game').after(lobbyRules);
const book=$('rules'),nav=el('div','rule-tabs'),overview=el('div','rule-overview'),visual=el('div','rule-visual');for(const n of [...book.children])if(!n.classList.contains('close'))overview.append(n);book.append(nav,overview,visual);visual.hidden=true;const showRules=button('How to play',()=>{overview.hidden=false;visual.hidden=true;}),showCards=button('Card Types',()=>{overview.hidden=true;visual.hidden=false;});nav.append(showRules,showCards);for(const [label,type] of [['Legendaries','legendary'],['Hearts','heart'],['Utility','utility'],['Jokers','joker'],['Instants','instant'],['Relics','relic'],['Non-playable','other']]){const section=el('details','rules-card-type'),summary=el('summary','',label),grid=el('div','rules-card-gallery');section.open=true;section.append(summary);if(type==='joker'||type==='instant')section.append(el('p','',type==='joker'?'2 of 6 Jokers per game':'8 Instants. Heart Collector and Death’s Door are guaranteed and cannot be replaced.'));const seen=new Set();for(const c of [...C.cards,...C.futureCards.filter(c=>c.setupPending)].filter(c=>type==='relic'?c.classification==='relic':type==='other'?['bad','dud'].includes(c.type)&&c.classification!=='relic':c.type===type)){const groupedNumber=type==='utility'&&Number(c.rank)>=2&&Number(c.rank)<=10;const key=groupedNumber?'number-'+c.rank:c.name;if((groupedNumber||['Full Moon','Blood Pact'].includes(c.name))&&seen.has(key))continue;seen.add(key);const card=cardNode(c.id);if(groupedNumber){card.querySelector('.card-top>span').textContent=c.rank;const count=C.cards.filter(other=>other.type==='utility'&&other.rank===c.rank).length;const copies=el('span','catalogue-copy-badge','×'+count);copies.setAttribute('aria-label',count+' matching cards');card.append(copies);}if(['Full Moon','Blood Pact'].includes(c.name)){const copies=el('span','catalogue-copy-badge',c.name==='Full Moon'?'×3':'×2');copies.setAttribute('aria-label',(c.name==='Full Moon'?'3':'2')+' copies');card.append(copies);}if(c.setupPending)card.append(el('span','catalogue-pending','DRAW EFFECT PENDING'));grid.append(card);}section.append(grid);visual.append(section);}

function copiedCardNode(id,source,small=false){const n=cardNode(source,small);n.dataset.card=id;n.dataset.copiedSource=source;n.classList.add('copied-joker');n.setAttribute('aria-label',C.byId[id].name+' copying '+C.byId[source].name);for(const opposite of [false,true]){const badge=el('span','joker-badge'+(opposite?' joker-badge-opposite':''));badge.innerHTML=HOHArt.markup('joker2');n.append(badge);}n.append(el('span','copy-identity',C.byId[id].name));return n;}
async function animateCopyTransform(e){const old=$('played').querySelector('.card'),rect=old?.getBoundingClientRect();let ghost;if(old&&rect){ghost=old.cloneNode(true);freezeFlightAppearance(old,ghost);Object.assign(ghost.style,{position:'fixed',left:rect.left+'px',top:rect.top+'px',width:rect.width+'px',height:rect.height+'px',margin:'0',zIndex:'200',pointerEvents:'none'});document.body.append(ghost);}render();const fresh=$('played').querySelector('.card');if(matchMedia('(prefers-reduced-motion: reduce)').matches){ghost?.remove();await wait(200);return;}try{const animations=[];if(ghost)animations.push(ghost.animate([{opacity:1,filter:'brightness(1)',transform:'scale(1)'},{opacity:0,filter:'brightness(2.1)',transform:'scale(1.05)'}],{duration:750,easing:'ease-in-out',fill:'forwards'}).finished);if(fresh)animations.push(fresh.animate([{opacity:.05,filter:'brightness(2)',transform:'scale(.96)'},{opacity:1,filter:'brightness(1)',transform:'scale(1)'}],{duration:850,easing:'ease-in-out'}).finished);await Promise.all(animations);}catch{}finally{ghost?.remove();}await wait(350);}
async function animateRewind(moves){$('status').textContent='Rewinding to the start of your previous turn…';if(matchMedia('(prefers-reduced-motion: reduce)').matches){await wait(350);return;}const overlay=el('div','rewind-overlay');overlay.append(el('span','rewind-caption','REWIND'));document.body.append(overlay);const locate=z=>{const n=z.zone==='deck'?$('draw-pile'):z.zone==='hand'&&z.player===0?$('hand'):z.zone==='hand'||z.zone==='effect'?$('seat-'+z.player):$('played');const r=n?.getBoundingClientRect();return r?{x:r.left+r.width/2,y:r.top+r.height/2}:{x:innerWidth/2,y:innerHeight/2};};try{const ctx=soundContext();[880,659,440,220].forEach((f,i)=>soundTone(ctx,f,i*.24,.7,.04,'triangle',f*.55));}catch{}try{for(let start=0;start<moves.length;start+=12){await Promise.all(moves.slice(start,start+12).map(async(m,i)=>{const from=locate(m.from),to=locate(m.to),n=m.card?cardNode(m.card,true):el('div','rewind-back '+(m.back==='purple'?'purple':'standard'),'♥');n.classList.add('rewind-traveler');Object.assign(n.style,{left:(from.x-38)+'px',top:(from.y-56)+'px'});overlay.append(n);try{await n.animate([{opacity:0,transform:'translate(0,0) rotate(8deg) scale(.85)'},{offset:.15,opacity:1,transform:'translate(0,-12px) rotate(2deg) scale(1)'},{opacity:1,transform:'translate('+(to.x-from.x)+'px,'+(to.y-from.y)+'px) rotate(-5deg) scale(.8)'}],{duration:1100,delay:i*90,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'}).finished;}catch{}finally{n.remove();}}));}if(!moves.length)await wait(1000);}finally{overlay.remove();}}

// One carnival cue per Joker play; another Joker restarts it without overlapping tracks.
var jokerMusic,jokerMusicTimer;
function stopJokerMusic(){clearInterval(jokerMusicTimer);jokerMusicTimer=null;if(jokerMusic){jokerMusic.pause();jokerMusic.currentTime=0;}}
function playJokerMusic(){stopJokerMusic();if(!jokerMusic){jokerMusic=new Audio('joker-carnival.mp3');jokerMusic.preload='auto';jokerMusic.loop=false;jokerMusic.addEventListener('ended',stopJokerMusic);}const music=jokerMusic;HOHSettings.bind(music,'music',.55);music.play().catch(()=>{});jokerMusicTimer=setInterval(()=>{const fade=Math.max(0,(music.currentTime-14)/3);HOHSettings.volume(music,.55*Math.max(0,1-fade));if(fade>=1)stopJokerMusic();},40);}
window.addEventListener('pagehide',stopJokerMusic);

var boardSelection;
function paintBoardSelection(){if(!boardSelection)return;const s=boardSelection;for(const opt of s.opts){const node=s.kind==='player'?$('seat-'+opt.value):[...document.querySelectorAll('#seat-'+s.subject+' [data-effect-card]')].find(n=>n.dataset.effectCard===opt.value);if(node){node.classList.add('target-choice');node.tabIndex=0;node.setAttribute('role','button');node.setAttribute('aria-label',s.kind==='player'?'Choose '+opt.label:'Pass '+opt.label);}}$('status').textContent=s.title+' · '+Math.max(0,Math.ceil((s.deadline-Date.now())/1000))+'s';}
function chooseOnBoard(title,opts,kind,subject){return new Promise(resolve=>{const finish=value=>{clearInterval(timer);document.removeEventListener('click',click,true);document.removeEventListener('keydown',keydown,true);boardSelection=null;choiceResolve=null;render();resolve(value);};const selected=target=>{const node=target.closest(kind==='player'?'.seat':'[data-effect-card]');if(!node)return;const value=kind==='player'?Number(node.id.replace('seat-','')):node.dataset.effectCard;if(opts.some(o=>o.value===value))return {value};};const click=e=>{const choice=selected(e.target);if(choice){e.preventDefault();e.stopPropagation();finish(choice.value);}};const keydown=e=>{if(e.key==='Enter'||e.key===' '){const choice=selected(e.target);if(choice){e.preventDefault();e.stopPropagation();finish(choice.value);}}};boardSelection={title,opts,kind,subject,deadline:Date.now()+30000};choiceResolve=finish;const timer=setInterval(()=>{paintBoardSelection();if(Date.now()>=boardSelection.deadline)finish(opts[0]?.value);},100);document.addEventListener('click',click,true);document.addEventListener('keydown',keydown,true);render();});}
function showCardDetails(id){let dialog=$('card-details');if(!dialog){dialog=el('dialog','card-details');dialog.id='card-details';document.body.append(dialog);}const c=C.byId[id];const close=button('×',()=>dialog.close(),'card-detail-close');close.setAttribute('aria-label','Close card information');const eyebrow=el('span','card-detail-eyebrow','CARD INFORMATION');dialog.replaceChildren(close,eyebrow,el('h2','',c.name),el('p','',c.rulesText||c.text));if(c.removalCost)dialog.append(el('p','removal-detail','Removal cost: shuffle '+c.removalCost+' Legendary Card'+(c.removalCost===1?'':'s')+' from your hand into the Draw Pile. Uses 1 action on your turn.'));dialog.showModal();}
async function animatePass(e){render();const old=[...document.querySelectorAll('#seat-'+e.from+' [data-effect-card]')].find(n=>n.dataset.effectCard===e.card),to=$('seat-'+e.target);if(!old||!to||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rect=old.getBoundingClientRect(),dest=to.getBoundingClientRect(),clone=old.cloneNode(true);freezeFlightAppearance(old,clone);Object.assign(clone.style,{position:'fixed',left:rect.left+'px',top:rect.top+'px',width:rect.width+'px',height:rect.height+'px',margin:'0',zIndex:'250',pointerEvents:'none'});document.body.append(clone);old.style.visibility='hidden';try{await clone.animate([{transform:'translate(0,0) rotate(0)'},{transform:'translate('+(dest.left+dest.width/2-rect.left-rect.width/2)+'px,'+(dest.top+dest.height/2-rect.top-rect.height/2)+'px) rotate(4deg)'}],{duration:1000,easing:'ease-in-out',fill:'forwards'}).finished;}catch{}finally{clone.remove();old.style.visibility='';}}

function updatePrivateLegendaryCount(){let counter=$("private-legendary-count");if(!counter){counter=el("span","private-legendary-count");counter.id="private-legendary-count";document.querySelector(".hand-heading").append(counter);}const count=game.owned(game.players[0]).filter(id=>game.isLegend(id)).length;counter.textContent="Your Legendary count: "+count;counter.title="End-game count: Legendaries and Jokers, including protected cards. Relics do not count.";}






